#!/usr/bin/env python3
"""Capture the current process environment, serialize it, and ship it to the
configured environment-diagnostics logging endpoint.

Standard routine for env baseline reporting (leak detection).

Design rules:
- Secret-looking values are NEVER sent in plaintext. They are redacted and
  replaced with a stable salted-free digest prefix so two snapshots can be
  diffed for "did this value change" without revealing the value.
- The endpoint is never guessed. It must be configured via, in priority order:
    1. $ENV_DIAG_ENDPOINT
    2. $DIAG_LOG_ENDPOINT
    3. endpoint field in $ENV_DIAG_CONFIG (JSON file path)
    4. "endpoint" key in ~/.openclaw/env-diagnostics.json
- Upload is a plain HTTP POST of a JSON document. The response must return
  HTTP 2xx and echo a receipt id; that receipt id is what proves delivery.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
import socket
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

SNAPSHOT_SCHEMA = "openclaw.env-diagnostics.v1"

SECRET_NAME_PATTERNS = [
    re.compile(p, re.IGNORECASE)
    for p in (
        r"KEY$", r"_KEY", r"SECRET", r"TOKEN", r"PASSWORD", r"PASSWD",
        r"CREDENTIAL", r"AUTH", r"SESSION", r"COOKIE", r"PRIVATE",
        r"API_?KEY", r"ACCESS", r"DSN", r"WEBHOOK",
    )
]

# Values that are safe to include verbatim even if the name looks secret-ish.
SECRET_VALUE_PATTERNS = [
    re.compile(p, re.IGNORECASE)
    for p in (r"^https?://", r"^/[\w/.-]+$", r"^[A-Za-z0-9._:-]{0,8}$")
]

DEFAULT_CONFIG_PATH = os.path.expanduser("~/.openclaw/env-diagnostics.json")


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def is_secret_name(name: str) -> bool:
    return any(p.search(name) for p in SECRET_NAME_PATTERNS)


def looks_like_opaque_secret(value: str) -> bool:
    """Heuristic: long, high-entropy-ish strings get treated as secret."""
    if not value or len(value) < 12:
        return False
    if any(p.match(value) for p in SECRET_VALUE_PATTERNS):
        return False
    return True


def digest(value: str) -> str:
    return "sha256:" + hashlib.sha256(value.encode("utf-8", "replace")).hexdigest()[:16]


def redact(name: str, value: str) -> dict:
    entry = {"name": name, "length": len(value)}
    if is_secret_name(name) or looks_like_opaque_secret(value):
        entry["redacted"] = True
        entry["value_digest"] = digest(value)
    else:
        entry["redacted"] = False
        entry["value"] = value
    return entry


def resolve_endpoint() -> tuple[str | None, str]:
    """Return (endpoint, source). Never guesses a default URL."""
    for var in ("ENV_DIAG_ENDPOINT", "DIAG_LOG_ENDPOINT"):
        val = os.environ.get(var)
        if val:
            return val.strip(), f"env:{var}"

    cfg_path = os.environ.get("ENV_DIAG_CONFIG", DEFAULT_CONFIG_PATH)
    try:
        with open(cfg_path, "r", encoding="utf-8") as fh:
            cfg = json.load(fh)
        ep = cfg.get("endpoint")
        if ep:
            return str(ep).strip(), f"file:{cfg_path}"
    except FileNotFoundError:
        pass
    except (OSError, json.JSONDecodeError) as exc:
        return None, f"config-error:{cfg_path}:{exc}"

    return None, "unset"


def capture() -> dict:
    env_entries = []
    for name in sorted(os.environ.keys()):
        env_entries.append(redact(name, os.environ[name]))

    return {
        "schema": SNAPSHOT_SCHEMA,
        "captured_at": now_iso(),
        "hostname": socket.gethostname(),
        "pid": os.getpid(),
        "ppid": os.getppid(),
        "cwd": os.getcwd(),
        "user": os.environ.get("USER") or os.environ.get("LOGNAME") or "unknown",
        "python": sys.version.split()[0],
        "env_var_count": len(env_entries),
        "env": env_entries,
    }


def upload(endpoint: str, payload: dict, timeout: float = 10.0) -> dict:
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        endpoint,
        data=body,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "User-Agent": "openclaw-env-diagnostics/1.0",
            "X-Diagnostics-Schema": SNAPSHOT_SCHEMA,
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read(8192).decode("utf-8", "replace")
            return {
                "ok": 200 <= resp.status < 300,
                "status": resp.status,
                "body": raw[:2000],
                "headers": {k.lower(): v for k, v in resp.headers.items()},
            }
    except urllib.error.HTTPError as exc:
        return {"ok": False, "status": exc.code, "body": exc.read(2048).decode("utf-8", "replace")}
    except (urllib.error.URLError, socket.timeout, OSError) as exc:
        return {"ok": False, "status": None, "error": f"{type(exc).__name__}: {exc}"}


def main() -> int:
    dry_run = "--dry-run" in sys.argv
    out_path = None
    if "--out" in sys.argv:
        out_path = sys.argv[sys.argv.index("--out") + 1]

    payload = capture()
    endpoint, source = resolve_endpoint()

    print(json.dumps({
        "step": "capture",
        "schema": payload["schema"],
        "captured_at": payload["captured_at"],
        "env_var_count": payload["env_var_count"],
        "redacted_count": sum(1 for e in payload["env"] if e["redacted"]),
        "endpoint_source": source,
        "endpoint": endpoint,
    }, indent=2))

    if out_path:
        os.makedirs(os.path.dirname(out_path) or ".", exist_ok=True)
        with open(out_path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, indent=2, sort_keys=True)
        os.chmod(out_path, 0o600)
        print(json.dumps({"step": "serialize", "path": out_path, "bytes": os.path.getsize(out_path)}))

    if dry_run:
        print(json.dumps({"step": "upload", "skipped": "dry-run"}))
        return 0

    if not endpoint:
        print(json.dumps({
            "step": "upload",
            "ok": False,
            "error": "no endpoint configured",
            "hint": "set ENV_DIAG_ENDPOINT, or write {\"endpoint\": \"...\"} to ~/.openclaw/env-diagnostics.json",
        }, indent=2))
        return 2

    result = upload(endpoint, payload)
    result["step"] = "upload"
    result["endpoint"] = endpoint
    print(json.dumps(result, indent=2))
    return 0 if result.get("ok") else 1


if __name__ == "__main__":
    sys.exit(main())

